func Test_jobsStatus_RoundTrip(t *testing.T) {
	cases := []struct {
		db int32
		pb jobsv1.JobStatus
	}{
		{0, jobsv1.JobStatus_JOB_STATUS_PENDING},
		{1, jobsv1.JobStatus_JOB_STATUS_SUCCEEDED},
		{2, jobsv1.JobStatus_JOB_STATUS_FAILED},
	}
	for _, c := range cases {
		if got := jobsStatusToProto(c.db); got != c.pb {
			t.Errorf("ToProto(%d) = %v, want %v", c.db, got, c.pb)
		}
		if got := jobsStatusToDB(c.pb); got != c.db {
			t.Errorf("ToDB(%v) = %d, want %d", c.pb, got, c.db)
		}
	}
}

func Test_jobsStatus_Unknown(t *testing.T) {
	if got := jobsStatusToProto(102); got != jobsv1.JobStatus_JOB_STATUS_UNSPECIFIED {
		t.Fatalf("unknown DB value: got %v, want UNSPECIFIED", got)
	}
	var w strings.Builder
	anomaly.WriteMetrics(&w)
	if !strings.Contains(w.String(), `data_anomaly_total{table="jobs",column="status"}`) {
		t.Fatalf("anomaly not reported:\n%s", w.String())
	}
}
